sys_variable_value.value:
(function execute(inputs, outputs) {
    try {
        // Get the name of the person the reservation is for.
        // Ternary guards against an empty reference input
        var reservedFor = inputs.reserved_for
            ? inputs.reserved_for.getValue('name')
            : 'Unknown';

        // Get the workspace name from the Workspace Options record
        var workspace = inputs.workspace
            ? inputs.workspace.getValue('workspace_name')
            : 'Unknown';

        // Convert raw date/time input to human-readable format.
        // + '' coerces the input to a string so GlideDateTime accepts it
        var startDate = 'Unknown';
        if (inputs.start_date_time) {
            var gdt = new GlideDateTime();
            gdt.setValue(inputs.start_date_time + '');
            startDate = gdt.getDisplayValue();
        }

        // Build the clickable link to the tracker record.
        // glide.servlet.uri holds your instance's base URL —
        // never hardcode the instance name here
        var trackerLink = '';
        if (inputs.tracker_record) {
            var trackerNumber = inputs.tracker_record.getValue('number');
            var trackerSysId = inputs.tracker_record.getUniqueValue();
            var instance = gs.getProperty('glide.servlet.uri');
            var url = instance +
                'nav_to.do?uri=x_1903615_worksp_0_reservation_tracker.do' +
                '?sys_id=' + trackerSysId;

            // \n = new line in Discord message
            trackerLink = '\n\uD83D\uDCC4 Reservation ' + trackerNumber + ': ' + url +
                '\n\uD83D\uDC4B Who can claim this one?';
        }

        // Compose the full message
        var message = 'Workspace reservation approved for ' + reservedFor +
            ' - ' + workspace +
            ' on ' + startDate +
            trackerLink;

        // Hand off to the Script Include for delivery —
        // this action decides WHAT to say, not HOW to send it
        var discord = new discordNotification();
        discord.sendMessage(message, '\u2705');

    } catch (ex) {
        // Log any failure without crashing the flow
        gs.error('Discord approval error: ' + ex.message);
    }
})(inputs, outputs);

